"use strict";

// Walkthroughs for the Using Kyro family part b (see howto-walkthroughs.js, walkthrough-kit.js and guide-walkthroughs.js). Kept in its own file so two writers can work on one family without touching the same lines.
// Part b: the farm, health and business parts of Kyro. Every phrase a step tells the person to say is quoted exactly as the how-to sheets and the live voice cases have it; a few short words that are in the sheets but not in the
// list of checked phrases (yes, skip, undo my last entry) are written without quotes. Where the sheets mark a part as needing review, practice only or phone only, the first step says so in the sheets' own words.

const { S, W } = require("./walkthrough-kit.js");

const KYRO = W("Kyro", "the helper you talk to or type to. It listens, answers, and shows results on the screen.");
const ORB = W("Orb", "the round shape on the Kyro screen. You tap it and speak.");
const SIGNED_IN = W("Signed in", "logged in with your own account, so the records you make belong to you.");

module.exports = {
  "farm-log": {
    title: "Using the farm log for rain, tank, soil and harvests",
    topic: "howto-farm-log", phrase: "using the farm log",
    steps: [
      S("Learn what the farm log keeps", `The farm log is Kyro's notebook for your farm. You tell Kyro what happened, in your own words, and it writes it down with the day. It keeps rain, soil moisture, the water level in your tank, and your harvests, and it adds them up when you ask. Be signed in, so the notes are yours. Kyro does not measure anything. It only writes down what you tell it.`, ["Your phone or computer with Kyro open and signed in"], null, "you can say in your own words that Kyro writes down only what you tell it.", [KYRO, SIGNED_IN, W("Log", "a written record of what happened, with the day it happened.")]),
      S("Open your farm log", `Tap the orb and say "Show my farm log." Your farm log comes up on the screen. If you have written nothing yet, it says your farm log is empty and tells you how to add to it. That is correct for a new log. When you want to go back to the orb, say close it.`, ["Your phone or computer with Kyro open"], null, "the farm log is on your screen, either with entries or saying it is empty.", [ORB]),
      S("Write down the rain", `Say "It rained about 12 mm today." Use your own number when you really log rain. The letters mm mean millimetres of rain. Kyro answers that it logged 12 mm of rain for today. Then ask "How much rain did we get this month?" Kyro gives the total for the month, for example 12 mm over 1 day.`, ["Your phone or computer with Kyro open", "How much rain fell, as best you can tell"], null, "Kyro has said it logged your rain and has told you the total for the month.", [W("Millimetre", "a small measure of length. Rain is counted in millimetres of water that fell.")]),
      S("Write down the tank and a harvest", `Say "The tank is at forty percent." Kyro says it logged the tank at 40 percent for today. Ask "What is the tank level?" and it tells you the last level you gave. Then say "I harvested forty kilos of maize." Kyro logs 40 kilos of maize and tells you the total for the year. Ask "How much maize have I harvested this year?" to hear it again.`, ["The tank level you can see", "What you harvested, in kilos"], null, "you have logged a tank level and a harvest, and Kyro has read each one back to you.", [W("Kilo", "short for kilogram, a measure of weight. A sack of maize is often counted in kilos.")]),
      S("Set a low tank warning", `Say "Warn me if the tank drops below 20 percent." Kyro says it will warn you when you log the tank below 20 percent. Later, if you say "The tank is at 15 percent," Kyro logs it and adds that it is below your alert. To stop the warning, say "Stop warning me about the tank." Kyro does not watch the tank. The warning comes only when you tell it a low number.`, ["The tank level that worries you, as a number"], null, "you know that the warning only comes when you say a low number yourself.", [W("Warning", "a message from Kyro that a number you logged is below the level you chose.")]),
      S("Fix a mistake", `If you logged a wrong number, say undo my last entry. Kyro removes your latest entry and tells you what it took away, for example 12 mm of rain for today. Then say the right number again. Look at the log once more to be sure only the wrong entry is gone.`, ["The log open, so you can check it"], null, "the wrong entry is gone and the right one is in your farm log.", [W("Entry", "one line in your log, such as one rain reading.")]),
      S("Keep one small habit", `Pick a time each evening and tell Kyro what happened that day on the farm: rain, tank, harvest. It takes less than a minute. After a few weeks your log shows a real picture of your season, and Kyro can add it up for you. Kyro cannot see your tank or your sky, so a reading you skip is a reading you do not have.`, ["A time of day you will remember, such as after supper"], null, "you have chosen a time each day to tell Kyro what happened on the farm.", [])
    ]
  },

  "fields": {
    title: "Using fields and planting records to track each plot",
    topic: "howto-fields", phrase: "using fields and planting records",
    steps: [
      S("Learn what a field record holds", `A field record is a page in Kyro for one plot of land. It holds the size, what is growing, when it was planted, and when you expect to harvest. Kyro can also make a crop calendar for the field. You tell Kyro everything by speaking, and be signed in so the records are yours. Kyro keeps only what you say.`, ["Your phone or computer with Kyro open and signed in", "The name and size of one of your plots"], null, "you can name the things a field record holds: size, crop, planting date and expected harvest.", [KYRO, SIGNED_IN, W("Acre", "a measure of land. One acre is a bit smaller than a football field.")]),
      S("Add a field", `Say "Add a field called North Plot, 2 acres." Use your own plot name and size. Kyro then asks short questions, one at a time: what is growing, when it was planted, and how much you expect to harvest. Answer the first one, for example maize. For any you do not know, say skip. Kyro moves on and does not save the word skip as an answer. At the end Kyro says it added North Plot, 2 acres, maize.`, ["The crop, the planting date and the expected harvest, if you know them"], null, "Kyro has said it added your field with its size and crop.", []),
      S("Check your fields", `Say "Show my fields." Kyro lists your fields. On a new account it says you have no fields yet. Make sure the field you just added is on the list, with the right size and crop. If something is wrong, remove the field and add it again, as the last step shows.`, ["Your phone or computer with Kyro open"], null, "your new field is on the list with the right size and crop.", []),
      S("Record a planting", `Say "I planted maize in North Plot on 12 March." Say the crop and the field name first, then the date. If you say the date before the field name, Kyro does not understand yet. Sizes like half an acre and two and a half acres are read correctly.`, ["The crop, the field name and the planting date"], null, "Kyro has said it recorded the planting for your field.", []),
      S("Make a crop calendar", `Say "Make a crop calendar for North Plot." Kyro makes a crop calendar for that field. The sheets do not say more about what the calendar shows, so read what comes up on the screen. If you are not sure it is right for your crop and your area, ask the owner or an adviser near you.`, ["The field name and its crop"], null, "a crop calendar for your field is on the screen, and you have read it.", [W("Crop calendar", "a plan of the jobs and dates for growing one crop through the season.")]),
      S("Remove a field you no longer need", `Only do this for a field you want gone. Say "Remove the field North Plot." Kyro asks if you want to remove it and says to say yes to go ahead, or no to leave it. Say yes. Kyro says it removed the field, and the list no longer shows it. Say no if you are not sure.`, ["The exact name of the field you want to remove"], null, "Kyro has asked you to confirm, and you have said yes or no on purpose.", [])
    ]
  },

  "stock": {
    title: "Keeping track of stock in the shed: seed, fertilizer and tools",
    topic: "howto-stock", phrase: "keeping track of stock in the shed",
    steps: [
      S("Learn what the shed stock keeps", `Shed stock is Kyro's count of what you keep: seed, fertilizer, chemicals, feed and tools. It keeps quantities, low levels and expiry dates, and it refuses to let you use more than you have recorded. It counts only what you tell it. Kyro does not count your stock by itself. Be signed in so the count is yours.`, ["Your phone or computer with Kyro open and signed in"], null, "you can say that Kyro counts only what you tell it.", [KYRO, W("Stock", "the things you keep in the shed, such as bags of seed or fertilizer."), W("Expiry date", "the day after which a product should not be used.")]),
      S("Add something to the shed", `Say "Add forty bags of fertilizer to stock." Kyro answers that it added 40 bags of fertilizer and that you now have 40 bags. You can say numbers in words or in digits. Use your own item and amount.`, ["What you have in the shed and how many"], null, "Kyro has said how many bags you now have.", []),
      S("Ask how much you have", `Say "How much fertilizer do I have?" Kyro answers that you have 40 bags of fertilizer. Ask with the words how much. The tester sheet says the words how many bags are not reliable yet, so use how much. Check that the answer matches what you really have in the shed.`, ["A look at the real shed, to compare"], null, "the number Kyro gave matches what is in your shed.", []),
      S("Write down what you used", `When you take some out, tell Kyro. Say "Use two bags of fertilizer." Kyro answers that it used 2 bags and that 38 bags are left. You can also say "I used 5 bags of fertilizer." Do this each time you use something, so the count stays true.`, ["The amount you took out of the shed"], null, "Kyro has said how many are left after you used some.", []),
      S("See how Kyro protects your count", `Kyro will not let your count go below zero. Try it once: say "Use 500 bags of fertilizer." Kyro answers that you only have 38 bags, so it has not changed anything. Your count stays the same. If this happens when you did mean a smaller number, check your last entries and say the amount again.`, ["The count Kyro last told you"], null, "Kyro has refused an amount bigger than your stock and the count did not change.", []),
      S("Remove an item and keep the count true", `If you no longer keep an item, say remove fertilizer from inventory. Kyro asks you to confirm, and you answer yes. The sheets do not give words for setting a low level or an expiry date, so ask the owner if you want those. The count is only as true as what you tell Kyro, so say it each time you add or use stock.`, ["The name of the item you want to remove"], null, "you know how to remove an item, and you know the count depends on what you tell Kyro.", [])
    ]
  },

  "animals": {
    title: "Keeping animal records for your cows, goats and other animals",
    topic: "howto-animals", phrase: "keeping animal records",
    steps: [
      S("Learn what an animal record holds", `An animal record is a page in Kyro for one animal. It can hold the kind of animal, a tag or name, the breed and the birth date. It can also keep health events, weights and milk. Kyro can answer how many animals you have, and questions about one animal. These are records only. Kyro gives no diagnosis for a sick animal. The sheets say this part has no step by step test yet, so check each answer.`, ["Your phone or computer with Kyro open and signed in", "The name or tag of one animal"], null, "you can say that Kyro keeps records and does not diagnose a sick animal.", [KYRO, W("Health event", "something that happened to the animal's health, such as a vaccination."), W("Tag", "a number or mark on the animal's ear that tells it apart.")]),
      S("Add an animal", `Say "Add a cow called Daisy." Use your own animal and name. If Kyro asks for more details, such as the breed or the birth date, answer what you know. The sheets do not list the questions, so read what Kyro says and answer it.`, ["The animal's name or tag, and the breed and birth date if you know them"], null, "Kyro has said it added your animal.", []),
      S("Record a vaccination", `Say "Daisy was vaccinated for foot and mouth, next due in 6 months." Use the name of your animal, what it was vaccinated for, and when the next one is due. Kyro keeps it as a health event for that animal. Use the vaccine and timing your own vet or animal health worker gave you.`, ["The vaccine name and the due date, from your vet or the paper they gave you"], null, "Kyro has recorded the vaccination for your animal.", [W("Vaccination", "a medicine given to an animal ahead of time to protect it from a disease.")]),
      S("Count your animals", `Say "How many cows do I have?" Kyro tells you the count. Check it against the animals you really have. If the number is wrong, an animal may be missing from the records, so add it with the same words you used before.`, ["A count of your animals, to compare"], null, "Kyro's count matches your animals, or you know which one to add.", []),
      S("Ask about one animal", `Say "Tell me about Daisy." Use your own animal's name. Kyro reads back what it has for that animal. If it is missing a health event you remember, add it again. These are only your records, so for a sick animal call your vet or animal health worker.`, ["The name of one animal you added"], null, "Kyro has read back what it has for one animal, and you know it is only a record.", []),
      S("Know what to do when something is wrong", `Kyro gives no veterinary diagnosis. If an animal is sick, call your vet or animal health worker. The sheets do not say how to correct or remove an animal record, so ask the owner if you need that. Come back to Kyro afterwards and add what the vet did.`, ["The phone number of your vet or animal health worker, written down"], null, "you have the number of someone to call about a sick animal.", [])
    ]
  },

  "farm-money": {
    title: "Recording money in and out of the farm: spending, sales and profit",
    topic: "howto-farm-money", phrase: "keeping farm money records",
    steps: [
      S("Learn what the farm money record does", `The farm money record is Kyro's account book for your farm. You say what you spent and what you sold, and Kyro writes it down with the day. It then works out your earnings, your spending and your profit. A sentence like I sold bags of maize goes into this farm book. The business record book is a separate ledger. Be signed in so the book is yours.`, ["Your phone or computer with Kyro open and signed in"], null, "you can say that what you spent and sold goes into your farm money record.", [KYRO, W("Profit", "the money you earned minus the money you spent."), W("Ledger", "a book where money in and out is written down.")]),
      S("Record something you spent", `Say "Spent 5000 on fertilizer." Kyro answers that it recorded the spending. Say the money word too, such as shillings or dollars, because an amount with no currency is only recorded properly when you use one currency. If you say a day, such as yesterday, Kyro keeps that day. Otherwise it uses today.`, ["What you spent, how much, and what for"], null, "Kyro has said it recorded your spending.", [W("Currency", "the kind of money, such as shillings or dollars.")]),
      S("Record a sale", `Say "Sold 2 tonnes of maize at 40000 per tonne." Kyro records the sale and the income for the month. A price said with each is multiplied by how many, so "Sold 10 bags of maize at 3000 each" is recorded as 30,000. You can say 6k for 6,000. A sale takes goods out of your harvested stock only.`, ["What you sold, how much, and the price"], null, "Kyro has recorded your sale and the total is what you expected.", [W("Tonne", "a thousand kilos.")]),
      S("Ask for your totals", `Say "How much did I earn this month?" Kyro tells you your earnings. Then say "What is my profit this year?" Kyro answers with your income, your spending and the profit. Questions about one month or one year are answered for that time. If the numbers look wrong, check the entries you made.`, ["A paper note of what you recorded, to compare"], null, "Kyro has told you what you earned and your profit, and you checked them against your notes.", []),
      S("Record a sale on credit", `Sometimes a buyer pays later. Say "Sold 20 bags of maize to Otieno on credit for 60000." Kyro records the sale as owed, not as income yet. Ask "Who owes me?" and Kyro lists who owes you. When Otieno pays, say "Otieno paid 20000" for part, or "Otieno paid" for all. Kyro then counts the money as income.`, ["The buyer's name, what was sold, and the amount owed"], null, "Kyro lists the buyer as owing you, and you know how to say they paid.", [W("On credit", "the buyer takes the goods now and pays later.")]),
      S("Record something you bought on credit", `Say "Bought 5 bags of fertilizer from Wanjiru on credit for 12500." Kyro counts the cost now and remembers what you owe. Ask "What do I owe?" and it lists it. When you pay, say "I paid Wanjiru 5000." Kyro says how much you still owe and does not count a second cost. When you finish paying, say "I paid Wanjiru."`, ["The seller's name and what you owe"], null, "Kyro has said what you owe, and you know how to say you paid.", []),
      S("Fix a mistake or delete an entry", `To take back your last sale, say "Undo my last sale." If you said the wrong amount, say "That should be 8000" and Kyro changes the last entry. To remove one, say "Delete the 8000 expense." Kyro tells you what it removed. A deleted or corrected sale does not put the goods back in your stock, so fix the stock yourself.`, ["The entry you want to correct, and the right amount"], null, "the wrong entry is corrected or gone, and Kyro has said so.", []),
      S("Know what the farm money record cannot do", `Money in different currencies is reported separately and never added together. Kyro cannot record a debt with no purchase, such as I owe Wanjiru 5000. It keeps only what you tell it, so say each sale and spend. For help with your taxes or a loan, ask a person you trust, because Kyro only keeps the book.`, ["Your phone or computer with Kyro open"], null, "you can name two things the farm money record cannot do.", [])
    ]
  },

  "farm-buyers": {
    title: "Keeping farm buyers, orders and a for-sale notice",
    topic: "howto-farm-buyers", phrase: "keeping farm buyers and orders",
    steps: [
      S("Learn what the buyers list does", `The buyers list keeps the people you sell to. You can take an order from a buyer, mark it delivered, and post a for-sale notice for your community. Everything is a note in your notebook. Kyro does not contact the buyer, and no money moves. Be signed in so the notes are yours.`, ["Your phone or computer with Kyro open and signed in"], null, "you can say that Kyro only writes notes and contacts nobody.", [KYRO, W("Order", "a buyer's request for an amount of something at a price."), W("Notice board", "a place in Kyro where people in your community can see what is for sale.")]),
      S("Add a buyer", `Say "Add a buyer called John Otieno." Use a made-up name to practise first if you like. Kyro asks three short questions: the phone number, what the buyer buys, and where. Answer them, or say skip to each one. Kyro answers that it added the buyer.`, ["The buyer's name, and their phone and town if you want to save them"], null, "Kyro has said it added the buyer.", []),
      S("Take an order", `Say "Order from John: 50 kg of maize at 40 per kg." Kyro answers with the order number, what was ordered, and the total, for example order 1 for 50 kilos at 40 per kilo, 2,000 in all. Write down the order number.`, ["What the buyer wants, how much, and the price"], null, "Kyro has given you an order number and the right total.", [W("Kg", "short for kilogram, a measure of weight.")]),
      S("Mark the order delivered", `After you hand over the goods, say "Deliver order 1." If your order number is not 1, say deliver order and then the number Kyro gave you. Kyro answers that the order was delivered and records the income, for example 2,000. If you marked it by mistake, say "Undo my last sale."`, ["The order number from the last step"], null, "Kyro has said the order is delivered and the income is recorded.", []),
      S("Post a for-sale notice", `Say "Post for sale: 500 kg maize at 40 per kg." Kyro posts it. Everyone in your community can see it, but never your phone number. Only post what you really want to sell, and write down the listing number Kyro gives you. Say "Show my listings" to see your notices.`, ["What you want to sell, how much, and the price"], null, "Kyro has posted your notice and given you its number.", []),
      S("Take a notice down", `When the goods are sold, take the notice off the board. Say "Remove my listing for maize." If you have several, Kyro asks for the number. You can also say "Mark my maize listing sold," which closes it and keeps it in your history. Do this soon, because other people can see the board.`, ["The number of the listing, from the last step"], null, "your notice is removed or marked sold, and you checked the list.", []),
      S("Fix or remove a buyer", `To remove a buyer, say remove buyer John Otieno, using the name you saved, and then answer yes. Typed words such as add a customer are taken by these farm tools before the business record book, even for a business owner. Say business customer when you mean the business record book.`, ["The name of the buyer you want to remove"], null, "you know how to remove a buyer, and you know which list a typed customer goes to.", [])
    ]
  },

  "farm-tasks": {
    title: "Using farm tasks, workers, loans, the co-op and reports",
    topic: "howto-farm-tasks", phrase: "using farm tasks and workers",
    steps: [
      S("Learn what the smaller farm tools do", `Kyro has a set of smaller farm tools. They are jobs for workers, a season budget and loan planning, co-op members and dues, a farm journal, and printable reports. The sheets say these have no step by step test yet. If Kyro does not understand a sentence, write down the exact words you said, and tell the owner.`, ["Your phone or computer with Kyro open and signed in", "A pen and paper"], null, "you can name two of the smaller farm tools.", [KYRO, W("Co-op", "a group of farmers who work or sell together and share costs."), W("Dues", "the money each member of a group pays to the group.")]),
      S("Add a task and see your tasks", `Say "Add a task: spray the tomatoes on Friday." Use your own job and day. Then say "Show my tasks." Kyro reads your open tasks. Say "Show all my tasks" to hear the finished ones too.`, ["A job to do on your farm and the day to do it"], null, "your new task is in the list Kyro reads back.", [W("Task", "one job to be done, with a day if you give one.")]),
      S("Plan a loan on paper", `Say "Plan a loan of 50000 over 6 months." Kyro plans the loan with you. This is only planning. Kyro does not apply for a loan or move any money. Read the answer, write it down, and talk to a person you trust before you borrow.`, ["The amount you are thinking of borrowing and how long you want to repay"], null, "you have a loan plan on paper, and you know Kyro has not applied for anything.", [W("Loan", "money you borrow and must pay back, usually with extra.")]),
      S("Add a co-op member", `Say "Add a co-op member called Amina." Use the real name of a member of your group. Kyro keeps the list of members. The sheets mention dues too but give no words for them, so ask the owner how to record dues.`, ["The name of a member of your group"], null, "Kyro has said it added the member.", []),
      S("Print your farm report", `Say "Print my farm report." Kyro prints the farm summary. Say "Print our cooperative statement" for the profit statement of your co-op. Read the report and check it against your own notes.`, ["Your own notes, to compare with the report"], null, "you have read your farm report and compared it with your notes.", [W("Report", "a short page that adds up what is in your records.")]),
      S("Know what can go wrong", `The sheets say that a sentence starting with create a budget may not work as expected. If any of these sentences fail, write down the exact words and tell the owner. Kyro does not pay your workers or file anything for the co-op. It only keeps your notes and reports.`, ["A pen and paper to write down any sentence that fails"], null, "you know to write down any sentence Kyro did not understand.", [])
    ]
  },

  "market-prices": {
    title: "Using market prices and crop advice with sources",
    topic: "howto-market-prices", phrase: "using market prices and crop advice",
    steps: [
      S("Learn what market prices and crop advice do", `When you ask about a price or a crop, Kyro searches the web and answers with the pages it found. If it cannot find a page that says it, it tells you so instead of guessing. A price is never given from memory. Prices differ by market and by day, and Kyro may say that its sources disagree. That is correct and honest.`, ["Your phone or computer with Kyro open"], null, "you can say that Kyro answers with the pages it found and does not guess.", [KYRO, W("Source", "the web page an answer came from.")]),
      S("Ask for a price", `Say "What is the price of beans in Nakuru?" Use your own crop and town. Kyro answers with a price and lists the pages it used. It can take some seconds. You can also say "Search the web for maize prices in Kenya." Kyro then asks which town, county or region to use. Answer with your town.`, ["The crop and the market town you want"], null, "Kyro has answered with a price or said it could not find a checked price.", []),
      S("Read the sources", `Under the answer Kyro shows the pages it used. An answer with no pages is only a guess, so do not rely on it. If the pages give different prices, that is normal. Write down the price, the market and the day, so you can compare later.`, ["A pen and paper"], null, "you have written down the price, the market and the day.", []),
      S("Ask a crop question", `Say "When should I plant maize in Kisumu?" Use your own crop and place. Kyro answers with what its pages say. It may say that the sources gave no definite date. Say "Open crop help" for a screen where you can ask about a crop or a pest, and write in the farm log.`, ["The crop and the place you ask about"], null, "Kyro has answered your crop question, or said honestly that the sources gave no definite answer.", []),
      S("Know what to do when there is no answer", `If Kyro says it could not find a checked price, that is the honest answer. Ask a trader or a farmer near you at the market, and write down what they say. Kyro does not have price alerts, so it cannot tell you when a price changes.`, ["The name of someone at your market who knows prices"], null, "you know what to do when Kyro cannot find a checked price.", [])
    ]
  },

  "maps": {
    title: "Using the maps to see routes and estimate delivery times",
    topic: "howto-maps", phrase: "using the maps and routes",
    steps: [
      S("Learn what the maps can show you", `The map shows the road route between two places, with the distance and the travel time. Kyro can also estimate how long a delivery takes. That is an estimate from the route, not live tracking, and Kyro does not know where a real parcel is. The sheets say the maps have not been checked on a real phone yet.`, ["Your phone or computer with Kyro open and online"], null, "you can say that a delivery time is an estimate and not live tracking.", [KYRO, W("Route", "the roads you follow to get from one place to another.")]),
      S("Open the map", `Say "Open the map." The map fills the screen. Starting any other request closes it, and you can say close it to go back to the orb.`, ["Your phone or computer with Kyro open"], null, "the full-screen map is open.", [ORB]),
      S("Ask for a route", `Say "Show a route from Nairobi to Nakuru." Use two towns you know. The map draws the road route, and Kyro says the distance and time, about 155 kilometres and about 2 hours for this pair. If the map service is slow, the sheets say it falls back to a straight line between two of 28 big cities. Wait a few seconds for the real route.`, ["The names of the two towns"], null, "a route is on the map and Kyro has said the distance and the time.", []),
      S("Ask how long a delivery will take", `Say "When will my delivery from Nairobi to Nakuru arrive?" Use your own towns. Kyro answers with an estimate based on the route. Treat it as a rough guide and allow extra time. It is not a tracker for a real parcel.`, ["The two towns for your delivery"], null, "Kyro has given you a delivery time estimate, and you know it is only an estimate.", []),
      S("Add stops to a route", `Say "Show a route from Nairobi to Kisumu via Naivasha, Nakuru and Kericho." Each stop is marked on the map in order, named in the answer, and counted in the distance. The sheets checked about 348 kilometres for this one. If a stop is labelled oddly, the map service found an unexpected match for the name.`, ["The towns of your stops, in order"], null, "the stops are marked on the map in order, and Kyro has named them.", [W("Stop", "a place you pass through on the way to the end of the trip.")]),
      S("Know when the map does not work", `The free map services can be slow or busy. Kyro tries a place twice. If it still cannot, it says which place it could not find, or that the service did not answer, and still gives you a map link. Try the town name again, or a bigger town nearby. When you finish, say close it.`, ["Your phone or computer with Kyro open"], null, "you know what Kyro does when a place cannot be found.", [])
    ]
  },

  "gps": {
    title: "Using GPS to find where you are, save home and get directions",
    topic: "howto-gps", phrase: "using gps and saving home",
    steps: [
      S("Learn what GPS needs and what has been checked", `GPS uses your phone's location to tell you where you are, save places and give directions. It works on a phone. The sheets mark it as phone only and partly working. They say nothing has been checked on a real phone yet. Directions stop when the screen locks, and they use free map services that can be slow. So treat this as practice, and do not rely on it where you could get lost.`, ["Your phone with Kyro open, and a data connection"], null, "you know GPS is phone only and has not yet been checked on a real phone.", [KYRO, W("GPS", "the part of your phone that finds where you are on the earth.")]),
      S("Allow your phone's location", `Switch on location on your phone. When the browser asks if Kyro may use your location, tap Allow. On Android Chrome choose Allow while visiting the site, and on iPhone Safari choose Allow. If you tapped Block before, tap the lock next to the web address, then Site settings, then Location, then Allow, and ask again.`, ["Your phone with location switched on"], null, "your phone has allowed Kyro to use your location.", [W("Location", "the place on the map where your phone is right now.")]),
      S("Ask where you are", `Say "Where am I?" Kyro names a nearby road or place, gives the latitude and longitude with an accuracy in meters, and a short plus code. The place should match where you stand. If it does not, go outside if you can and ask again.`, ["Your phone, with you standing in a place you know"], null, "the place Kyro named matches where you stand.", [W("Latitude and longitude", "two numbers that say exactly where a place is on the earth."), W("Plus code", "a short code for a place, made of letters and numbers.")]),
      S("Save your home", `Stand at home and say "Save this place as home." Kyro answers that it saved this place as home and that it stays on this phone only. Only save a place that is yours.`, ["Your phone, with you at home"], null, "Kyro has said it saved this place as home.", []),
      S("Get directions home", `Later, when you are away, say "Take me home." A dark green bar appears at the bottom of the screen with the next instruction, the distance left and a Stop navigation button. Keep the screen on and the app open, because directions stop when the screen locks. When you want to end it, say "Stop navigation."`, ["Your phone with the screen on and location allowed"], null, "the green bar shows the next instruction, and you know how to stop it.", [W("Navigation", "step by step directions while you travel.")]),
      S("Forget a saved place", `To remove a saved place, say forget place home. Saved places stay on this phone only. A slow map service or a locked screen can stop directions, so also keep another way to find your way. If you feel unsafe or lost, call someone you trust or your local emergency number.`, ["Your phone"], null, "you know how to forget a place and what can stop the directions.", [])
    ]
  },

  "bp-log": {
    title: "Logging your blood pressure readings with Kyro",
    topic: "howto-bp-log", phrase: "logging my blood pressure",
    steps: [
      S("Learn what the blood pressure log does", `Kyro can save a blood pressure reading you say out loud, with the date. It refuses numbers that cannot be real, and it gives urgent guidance for a very high reading. Only you see your own readings. Kyro does not diagnose. The sheets say the limits and the urgent wording have not been reviewed by a clinician. Kyro is not a replacement for emergency help. If you feel very unwell, call your local emergency number.`, ["Your phone or computer with Kyro open and signed in, not as a guest"], null, "you can say that Kyro saves your readings and does not diagnose.", [KYRO, W("Blood pressure", "the force of your blood on the walls of your blood vessels. It is written as two numbers, such as 140 over 90."), W("Reading", "one measurement, with its two numbers.")]),
      S("Take your reading and write it down", `Measure your blood pressure the way your clinic or pharmacy showed you. Kyro does not measure it. Write the two numbers on paper, the top one first and then the bottom one. If you are not sure how to measure, ask your clinic or pharmacy. Do not guess a number to tell Kyro.`, ["A paper and pen", "Your blood pressure reading"], null, "you have your two numbers written on paper.", []),
      S("Say your reading and save it", `Say "My blood pressure is 140 over 90, please save it." Use your own numbers. Kyro may ask you to confirm, so say yes. Kyro says it saved the reading, adds that one reading is not a diagnosis, and says to see a clinician for severe symptoms. If Kyro says it noted the reading but could not save it, say yes, save it, again.`, ["Your two numbers on paper"], null, "Kyro has said it saved your reading.", []),
      S("See what Kyro does with a number that cannot be real", `If you say a number that cannot be a real reading, such as "My blood pressure is 900 over 20, please save it," Kyro says it does not sound real and does not save it. It asks you to say it again, for example 120 over 80. If that happens to you, look at your paper and say the numbers again, slowly.`, ["Your two numbers on paper"], null, "you know that Kyro refuses numbers that cannot be real and asks you to say them again.", []),
      S("Know what a very high reading looks like", `A very high reading gets urgent guidance from Kyro first. Follow what Kyro says. If you feel very unwell, call your local emergency number straight away. Kyro cannot call for you, and it cannot send help. The sheets say this guidance has not been reviewed by a clinician, so do not treat Kyro as your only help.`, ["Your local emergency number written down"], null, "you have your local emergency number written where you can find it.", []),
      S("Hear your history back", `Say "Show my blood pressure history." Or say "What is my blood pressure trend?" Kyro tells you how many readings it has saved and what they are, and says this is saved history and not a diagnosis. Each reading shows the day it was said. Only you can hear your readings.`, ["Your phone or computer with Kyro open"], null, "Kyro has read your saved readings back to you.", []),
      S("Take your readings to your clinic", `Bring your paper and tell your clinic what Kyro has saved. Ask the clinician what your numbers mean for you. Kyro gives no diagnosis and no treatment advice. The sheets say there is no voice command to delete one reading, so if you saved one by mistake, tell the owner or your clinic.`, ["Your paper with your readings", "A list of questions for your clinic"], null, "you have your readings and your questions ready for your clinic.", [W("Clinician", "a nurse, doctor or other health worker who looks after patients.")])
    ]
  },

  "sugar-log": {
    title: "Logging your blood sugar readings with Kyro",
    topic: "howto-sugar-log", phrase: "logging my blood sugar",
    steps: [
      S("Learn what the blood sugar log does", `Kyro can save a blood sugar reading you say out loud. It understands the two units, asks you when the unit is unclear, and refuses numbers that cannot be real. It gives urgent guidance for a very low or very high reading. Kyro gives no treatment advice. The sheets say the limits and the urgent wording have not been reviewed by a clinician. If you feel very unwell, call your local emergency number.`, ["Your phone or computer with Kyro open and signed in, not as a guest"], null, "you can say that Kyro saves your readings and gives no treatment advice.", [KYRO, W("Blood sugar", "the amount of sugar in your blood, measured with a meter."), W("mmol/L and mg/dL", "the two units a meter can show blood sugar in.")]),
      S("Write down your reading and its unit", `Look at your meter or your clinic paper. Write the number and its unit. Some meters show a number like 7.2 with mmol, and others show a number like 130 with mg per dL. If you are not sure which unit yours uses, ask your clinic or pharmacy. Do not guess a number to tell Kyro.`, ["Your meter reading or clinic paper", "A pen and paper"], null, "you have your number and its unit written on paper.", []),
      S("Save a reading in mmol", `Say "My blood sugar is 7.2 mmol, please save it." Use your own number. Kyro saves it. The sheets say the reading is stored in the other unit, mg per dL, and the history names the unit of each reading.`, ["Your number and unit on paper"], null, "Kyro has said it saved your reading.", []),
      S("Save a reading in mg per dL", `Say "My blood sugar is 130, please save it." A number like 130 is clearly in mg per dL, so Kyro saves it. Use your own number.`, ["Your number and unit on paper"], null, "Kyro has said it saved your reading.", []),
      S("See what Kyro does when the unit is not clear", `If you say a number that could be in either unit, such as "My blood sugar is 35, please save it," Kyro says it is not sure whether that is mmol per litre or mg per dL. It does not save it, and asks you to say it again with the unit. Say the number again and add the unit from your paper.`, ["Your number and unit on paper"], null, "you know that Kyro asks for the unit when it is not clear and does not save it until you say it.", []),
      S("Know what a very low or very high reading looks like", `A very low or very high reading gets urgent guidance from Kyro before and after saving. Follow what Kyro says. If you feel very unwell, call your local emergency number straight away. Kyro cannot call for you. Kyro does not say what to eat, and does not tell you how much medicine to take. Ask your pharmacist or clinic.`, ["Your local emergency number written down"], null, "you have your local emergency number written where you can find it.", []),
      S("Hear your readings back and take them to your clinic", `Say show me my saved chronic care readings. Kyro lists your saved readings and names the unit of each, for example glucose 7.2 mmol per litre. Take your paper to your clinic and ask the clinician what your numbers mean. Kyro does not diagnose. The sheets say there is no voice command to delete a single reading, so tell the owner if you saved one by mistake.`, ["Your paper with your readings", "Your questions for your clinic"], null, "Kyro has read your saved readings back, and you have your questions ready for your clinic.", [W("Chronic care", "ongoing care for a health condition that lasts a long time.")])
    ]
  },

  "wellbeing-log": {
    title: "Logging sleep, mood, water, weight and workouts",
    topic: "howto-wellbeing-log", phrase: "logging sleep, mood and water",
    steps: [
      S("Learn what the wellbeing log does", `The wellbeing log is a private diary in Kyro. You can tell it how long you slept, how your mood is, how much water you drank, your weight and your workouts. Kyro gives you summaries, a weekly workout goal, and personal bests for running distances. It works in English only. Be signed in so the log is yours.`, ["Your phone or computer with Kyro open and signed in"], null, "you can name two things you can log with Kyro.", [KYRO, W("Personal best", "your fastest or longest result so far.")]),
      S("Log your sleep and your mood", `Say "I slept seven hours." Kyro answers that it logged 7 hours of sleep for today. Then say "My mood is 4 out of 5." Kyro answers that it logged mood 4 out of 5 for today. Use your own numbers. Saying seven in words works as well as the digit.`, ["The hours you slept last night", "A number from 1 to 5 for your mood"], null, "Kyro has said it logged your sleep and your mood.", []),
      S("Log your water and your weight", `Say "I drank 2 liters of water." Kyro answers that it logged 2 liters of water for today. For your weight, say "I weigh 70 kg" with your own number. Kyro logs it as your weight, not as your age.`, ["How much water you drank", "Your weight, if you want to log it"], null, "Kyro has said it logged your water and your weight.", []),
      S("Log a workout", `Say "I ran 5 km in 30 minutes." Use your own distance and time. Kyro logs the run and tells you your pace, and if it is a personal best, it says so. Say "I did 30 minutes of football" for another sport. The sentence I played football for 30 minutes is not understood yet, so use the words as written here.`, ["Your distance and time, or the sport and minutes"], null, "Kyro has said it logged your workout.", [W("Pace", "how long it takes you to go one kilometre.")]),
      S("Ask for your summaries", `Say "How did I sleep this week?" Kyro tells you your average sleep. Say "Show my training log" to hear your entries, and say "Show my personal bests" to hear your best results. Look at the numbers and see if they match what you remember.`, ["Your phone or computer with Kyro open"], null, "Kyro has read you a summary of your sleep and your training.", []),
      S("Undo a workout", `If you logged a workout by mistake, say "Undo my last workout." Kyro says it removed the workout. Then say "Show my training log" and check that only the workout is gone. The sheets once warned that undo could remove your newest entry of any kind, so look at the log afterwards, and say the other entry again if it is gone.`, ["The log open, so you can check it"], null, "the workout is gone and your other entries are still in the log.", []),
      S("Keep one small habit", `Pick a time each evening, and tell Kyro your sleep, mood and water in one go. A small habit gives you a real picture of your week. Kyro is not a doctor and gives no medical advice from your log. If a number worries you, talk to your clinic.`, ["A time of day you will remember"], null, "you have chosen a time each day to tell Kyro how you are.", [])
    ]
  },

  "medicine-reminders": {
    title: "Using medicine reminders to remember each dose",
    topic: "howto-medicine-reminders", phrase: "using medicine reminders",
    steps: [
      S("Learn what medicine reminders do", `Kyro can remind you to take a medicine at times you choose, and you can tell it each time you took it. It only repeats what you say your clinic prescribed, and it cannot check doses. The sheets mark this part as needing review, and say the check for amounts that look too big is from a short table that a pharmacist should review. Reminders work in English only.`, ["Your phone or computer with Kyro open and signed in"], null, "you can say that Kyro repeats what you tell it and cannot check doses.", [KYRO, W("Reminder", "a message that tells you something at the time you chose."), W("Dose", "the amount of a medicine you take at one time.")]),
      S("Get your medicine details from your label or clinic", `Before you tell Kyro, have the name, the amount and the times exactly as your clinic or pharmacist told you or as printed on the label. Do not guess, and do not change anything because of Kyro. If you are not sure, ask your pharmacist or clinic. Kyro cannot check what you tell it.`, ["Your medicine label or clinic paper", "A pen and paper"], null, "you have the medicine name, the amount and the times written on paper from your label.", []),
      S("Add a medicine reminder", `Practise with this made-up example only, and use your own label for a real medicine: say "Add medication metformin 500mg at 8am and 8pm." Kyro repeats the medicine and the times, says it will remind you every day, and says it only repeats what you said was prescribed and cannot check doses. For your own medicine, use the same shape with the name, amount and times from your label.`, ["Your medicine details on paper"], null, "Kyro has repeated the medicine and the times back to you.", []),
      S("Check the amount if Kyro asks about it", `If you say an amount that looks far larger than usual for a common medicine, Kyro does not save it. It asks you to read the label, and says to add the word confirmed only if the amount is exact. Read your label or ask your pharmacist. Do not add confirmed unless you have checked.`, ["Your medicine label"], null, "you know Kyro asks about a large amount and you only confirm when you have checked the label.", []),
      S("See your list of medicines", `Say "What medications do I take?" Kyro lists your medicines and their times, for example the medicine at 8:00 am and 8:00 pm. Check them against your paper. If something is wrong, ask your pharmacist or clinic before you change anything.`, ["Your paper with your medicines"], null, "the list Kyro read matches your label.", []),
      S("Tell Kyro you took it, or that you missed it", `When you take a medicine, say "I took my metformin." Use your own medicine. Kyro answers that it logged it as taken. "I took my tablets this morning" works too. If you forgot, say "I missed my metformin." Kyro records it as missed, never as taken, and does not say if you should take it late. Ask your pharmacist or clinic about that.`, ["Your medicine, and a time you will check"], null, "Kyro has logged a dose as taken, and you know a missed dose is recorded as missed.", []),
      S("Tell your circle, stop a reminder, and know the limits", `You can say "Tell my circle if I miss a dose for 4 hours." Kyro then tells the people you chose if you miss a dose for that long, or after 2 hours if you set none. To stop, say "Stop reminding me about metformin." If your doctor stops a medicine, tell Kyro, and tell your clinic too. Phone alerts need alerts turned on, and no one has proven they arrive on the live site yet, so keep your usual way of remembering too.`, ["Your trusted circle set up, if you want them told", "Alerts turned on for your phone"], null, "you know how to tell your circle, how to stop a reminder, and that alerts are not proven yet.", [W("Circle", "the trusted people you chose to be told when you need help.")])
    ]
  },

  "checkins": {
    title: "Setting up daily check-ins with Kyro",
    topic: "howto-checkins", phrase: "setting up daily check-ins",
    steps: [
      S("Learn what a daily check-in is", `A daily check-in is a short message from Kyro at a time you choose. It asks how you are. If you do not answer for a while, Kyro can quietly let someone you trust know. It works in English only. A check-in is not emergency help. If you need help right now, call your local emergency number.`, ["Your phone with Kyro open and signed in"], null, "you can say that a check-in asks how you are and is not emergency help.", [KYRO, W("Check-in", "a short message that asks how you are, at a time you choose.")]),
      S("Choose the time and the people", `Think of a time each day when you can answer a message, such as eight in the morning. Think also about whether you want Kyro to tell someone if you do not answer. Those people are your trusted circle, so set that up first if you want it. Write down the time and the names.`, ["A pen and paper", "The time you will answer, and the names of your trusted people"], null, "you have a time and, if you want, the names written down.", []),
      S("Set your check-in", `Say "Check in on me every morning at 8." Use your own time. Kyro answers with the time and your time zone, and says that nobody will be told anything. Check that the time and the time zone are right. If they are not, say it again with the right time.`, ["The time you chose"], null, "Kyro has said the time of your check-in and that nobody will be told anything.", []),
      S("Choose when your circle is told", `If you want your circle told when you do not answer, say "Check in on me every morning at 8 and tell my circle after 6 hours." Or say "Tell my circle if I don't answer for 6 hours." The sheets say a missed check-in waits 3 hours before the people you chose are told, unless you set your own, between 1 and 24 hours. This needs alerts turned on and a registered phone.`, ["Your trusted circle already set up", "Alerts turned on for your phone"], null, "you know how long Kyro waits before it tells your circle, and you have chosen the time.", []),
      S("Answer a check-in", `When your check-in arrives on your phone, it reads like how are you today. Answer it, for example by saying I'm okay. Kyro replies kindly. The message only arrives if alerts are turned on for your phone. If you ever need help, call your local emergency number. Do not wait for a check-in.`, ["Your phone with alerts turned on"], null, "you know how to answer a check-in and what to do if you need help.", []),
      S("Check on it and stop it", `Say "Do I have check-ins?" Kyro tells you your check-in time. When you no longer want it, say "Stop my check-ins." Kyro says your check-ins are stopped. If you do not stop them, they keep coming every day.`, ["Your phone or computer with Kyro open"], null, "Kyro has told you your check-in time, and you know how to stop it.", [])
    ]
  },

  "circle": {
    title: "Setting up a trusted circle for emergency alerts",
    topic: "howto-circle", phrase: "setting up a trusted circle",
    steps: [
      S("Learn what a trusted circle is and what an alert does", `A trusted circle is a small group of people you choose. If you ask Kyro for help, it sends them a push alert on their phones. The sheets mark this as needing review. An alert is a push notification only. No text, phone call, ambulance or emergency service is contacted, and Kyro cannot tell whether their phone received it. If you are in danger, call your local emergency number first.`, ["Your phone with Kyro open and signed in"], null, "you can say that an alert only sends a notification and does not call anyone for help.", [KYRO, W("Trusted circle", "the people you chose to be told when you need help."), W("Push alert", "a message that pops up on a phone, without a text or a call.")]),
      S("Choose your people and ask them first", `Choose one or two people you trust. They must have their own Kyro account in your community, and they need alerts turned on for their phone. Ask them first, and tell them what an alert will look like. Write down the email address each person uses for Kyro. Do not put someone in your circle without asking them.`, ["A pen and paper", "The Kyro email of each person you chose"], null, "you have agreed it with each person and have their Kyro email written down.", []),
      S("Invite a person", `Type this, and replace MEMBER-EMAIL with your friend's email: "Add MEMBER-EMAIL to my circle as my friend". Typing is the way the sheets proved. Kyro answers that if that email has a Kyro account in your community, it has sent them your invitation. It sounds the same whether or not the email has an account, to protect people's privacy.`, ["Your friend's Kyro email"], null, "Kyro has said it sent the invitation.", []),
      S("Ask your friend to accept", `Your friend opens Kyro and says "Do I have any invitations?" Then they type "Accept the invitation from PERSON-FIRST-NAME", replacing PERSON-FIRST-NAME with your first name. They then get a thank-you saying they will only hear from Kyro about you in an emergency.`, ["Your friend, with Kyro open on their phone"], null, "your friend has accepted the invitation and has seen the thank-you.", []),
      S("Check who is in your circle", `Say "Who is in my circle?" Kyro lists the people. Make sure each person you asked is there. If someone is missing, ask them to look for the invitation and accept it.`, ["Your phone or computer with Kyro open"], null, "Kyro lists everyone you chose.", []),
      S("Know how an alert works before you ever need it", `If you ask Kyro for help, it sends the alert, for example when you say "Alert my circle." Kyro tells you who it alerted and says to call your local emergency number if you might be in danger. When you are safe, say "I'm safe," and Kyro tells your circle that you are okay. Do not practise this without telling your circle first. Two alerts within 5 minutes count as one. The sheets say some natural ways of describing an emergency may be missed, so call your emergency number first.`, ["Your circle told that you may practise at a set time"], null, "you know what an alert sends and how to close it, and you will tell your circle before you practise.", []),
      S("Change who is in your circle", `To remove a person, say remove their name from my circle. A person can also leave your circle themselves by saying leave your name's circle. Keep your circle small and up to date, and tell people when you remove them.`, ["The name of the person you want to remove"], null, "you know how to remove a person and how a person can leave.", [])
    ]
  },

  "health-worker": {
    title: "Using the health worker record book for patients and visits",
    topic: "howto-health-worker", phrase: "using the health worker record book",
    steps: [
      S("Learn what the health worker record book is", `The health worker record book is for community health workers. It keeps patients, visits, immunisations, pregnancies, referrals, supplies and monthly reports. A health worker's records are kept under their own account. The sheets also say that older demo records with no owner are shown to everyone, and that part of the health workspace screens uses shared or demo data. The sheets say this has no step by step test yet, so practise with made-up patients first.`, ["Your phone or computer with Kyro open and signed in", "A made-up patient name for practice"], null, "you can say why you practise with a made-up patient first.", [KYRO, W("Community health worker", "a trained person who gives basic health care and advice in their community."), W("Immunisation", "a vaccine given to protect someone from a disease.")]),
      S("Register a made-up patient", `Say "Register a patient called Grace." Use a made-up name while you practise. Kyro keeps the patient in your record book. Do not enter a real person's details until the owner tells you the book is ready for real patients.`, ["A made-up patient name"], null, "Kyro has said it registered your practice patient.", [W("Register", "write a person's name into the record book.")]),
      S("Record a visit", `Say "Record a visit for Grace." Kyro writes the visit in the record for that patient. The sheets do not say what else Kyro asks, so listen and answer. Kyro records what you tell it, and gives no diagnosis.`, ["The practice patient's name"], null, "Kyro has said it recorded the visit.", [W("Visit", "a meeting where you see a patient, with the date written down.")]),
      S("Print the monthly report", `Say "Print my monthly report." Kyro prepares your monthly report from the records. Read it and check it against your practice entries. If a number does not match, write down what you said and tell the owner.`, ["Your practice entries, to compare"], null, "you have a monthly report and have compared it with your practice entries.", []),
      S("Check that you only see your own records", `Each person's records should stay their own. If you ever see a record that you did not make, stop and tell the owner at once, and say which screen it came from. Do not copy or share it. Old demo records have no owner and show to everyone. An Admin should clear them.`, ["The owner's contact"], null, "you know to tell the owner at once if you see a record you did not make.", [W("Admin", "the person in charge of the Kyro accounts and settings.")]),
      S("Know what the sheets do not say", `The sheets give no words for immunisations, pregnancies, referrals or supplies, so ask the owner how to record those. Kyro keeps records only. It does not diagnose, it does not send a referral, and it does not contact a patient or a clinic for you. For an emergency, call your local emergency number.`, ["The owner's contact, to ask how to record those"], null, "you know what Kyro keeps and what it does not do for a patient.", [])
    ]
  },

  "find-care": {
    title: "Finding a clinic or pharmacy with Kyro",
    topic: "howto-find-care", phrase: "finding a clinic or pharmacy in kyro",
    steps: [
      S("Learn what Kyro can find and what it cannot", `Kyro can look for clinics and pharmacies near a town, and prepare a telehealth visit request. The sheets mark this as needing a partner. Results can come from other countries or from a small starter list. There is no network of doctors, and doctor search uses a United States directory. A video visit needs a video service that may not be set. Kyro does not book, call or contact a clinic. In an emergency, call your local emergency number.`, ["Your phone or computer with Kyro open and online"], null, "you can say that Kyro finds places and prepares a request, and does not book or call.", [KYRO, W("Telehealth", "seeing a health worker by video or phone instead of in person.")]),
      S("Open the health screen", `Say "Open health." The health screen opens with buttons to start a telehealth request, record blood pressure, and find a pharmacy or clinic. You can say "Open the pharmacy" for the same screen.`, ["Your phone or computer with Kyro open"], null, "the health screen is open.", []),
      S("Find a pharmacy", `Say "Find a pharmacy near Kisumu." Use your own town. A list of pharmacies near you comes up, with distances. It can take 10 to 15 seconds, so wait.`, ["The name of your town"], null, "a list of pharmacies is on your screen.", [W("Pharmacy", "a shop where medicines are sold and where a pharmacist can answer questions.")]),
      S("Find a clinic", `Say "Find a clinic near Kisumu." Use your own town. A list of clinics comes up. Take your time to read the names.`, ["The name of your town"], null, "a list of clinics is on your screen.", [W("Clinic", "a place where a nurse or doctor sees patients.")]),
      S("Check the results before you travel", `Look at the town and the country of each place. The sheets say results can come from other countries or a small starter list, so a place may not be near you. Kyro has not contacted any place for you. Before you travel, ask someone near you whether the place is real and open.`, ["The list on the screen", "The phone number of someone near you who knows"], null, "you checked the places are really in your area before planning a trip.", []),
      S("Prepare questions for your visit", `Say "Help me prepare questions for my next clinic visit." Kyro gives safe questions to bring to a pharmacist or clinic. It says it did not request a refill or transfer, change a dose, or contact a pharmacy, and it gives no dose. Write the questions down and take them with you.`, ["A pen and paper"], null, "you have a short list of questions on paper for your visit.", []),
      S("Start a telehealth request", `Say "Start a telehealth request." A panel opens, says to call your emergency number if this is an emergency, and asks what the visit is for. Kyro prepares the request. It does not contact anyone, and the sheets say there is no network of doctors. Ask the owner whether video visits are switched on.`, ["Your phone or computer with Kyro open"], null, "you saw the telehealth panel and know it only prepares a request.", [])
    ]
  },

  "business-records": {
    title: "Using the business record book for customers, leads and follow-ups",
    topic: "howto-business-records", phrase: "using the business record book",
    steps: [
      S("Learn what the business record book is", `The business record book keeps a small business, a nonprofit or a church in one place. Inside one workspace you can keep customers, leads, donors and volunteers, plus tasks, appointments and grants. Records are real and saved, but nothing is sent or published. Every write asks Should I go ahead, and you say yes to save. Sign in as yourself, because a guest is told there is no workspace yet.`, ["Your phone or computer with Kyro open and signed in"], null, "you can say that Kyro asks before it saves anything.", [KYRO, W("Workspace", "one business, nonprofit or church and all its records."), W("Lead", "a person who might become a customer.")]),
      S("Start your workspace", `Say "Start a business called Mama Grace Shop." Use your own name. Kyro answers that it can start a new workspace with that name and asks if it should go ahead. Say yes. If you say only start a business with no name, Kyro asks what to call it. A page called Business services shows the same records. If you cannot find it, ask the owner for its address.`, ["The name of your business"], null, "Kyro has said it started your workspace.", []),
      S("Add a customer and a lead", `Say "Add a business customer named Grace Otieno." Say the word business, so Kyro uses the business list. Say yes when it asks. Then say "Add a lead named John Kamau." Add one person in each sentence. Do not add a phone number in the same sentence.`, ["The name of one customer and one lead"], null, "Kyro has said it added both people.", []),
      S("Hear your customers back", `Say "Who are my customers?" Kyro names your customers and the follow-up day next to a name if one is set. Check that the people you added are there. The same records are on the Business services page.`, ["Your phone or computer with Kyro open"], null, "Kyro named the people you added.", []),
      S("Set a follow-up day", `Say set a follow-up with Grace Otieno on Friday, using your customer and the day. Kyro asks you to confirm and, after your yes, saves a real date on her row and says it will remind you when it is due. Ask who your customers are again, and the day shows next to her name.`, ["A customer name and a day"], null, "the follow-up day is saved on the customer.", []),
      S("Change or remove a record", `To change a stage, write notes, or edit or delete a person, use the row on the Business services page, then press Save changes. The sheets say a voice command cannot yet change a stage or add a note. There is no voice undo, and the workspace itself is removed by the organizer or the Delete this workspace button on the page. Adding the same person twice is refused.`, ["The Business services page open"], null, "you know a record is changed on the page and not by voice.", [])
    ]
  },

  "invoices": {
    title: "Making invoices and receipts, and tracking who owes you",
    topic: "howto-invoices", phrase: "making invoices",
    steps: [
      S("Learn what the invoice tools do", `An invoice is a bill you give a customer for what you sold them. Kyro can make an invoice, add items to it, show you who owes you, mark it paid, and give you a printable PDF. Nothing is sent to your customer. You give them the invoice yourself. You need a business workspace first. Every write asks Should I go ahead, and you say yes.`, ["Your phone or computer with Kyro open and a business workspace started"], null, "you can say that Kyro makes the invoice and you give it to the customer yourself.", [KYRO, W("Invoice", "a bill that lists what you sold and what the customer owes."), W("Line item", "one thing on the invoice, with its amount, such as 5 bags of maize.")]),
      S("Create an invoice", `Say "Create an invoice for Grace Otieno." Use your own customer's name. Kyro asks if it should go ahead. Say yes. Kyro answers that it created an invoice with a number such as INV-1001. The number is automatic. Say only the name in this sentence, and add the items in the next step.`, ["The customer's name"], null, "Kyro has given you an invoice number.", []),
      S("Add an item to the invoice", `Say "Add an item to invoice INV-1001: 5 bags of maize at 500 shillings each." Use the invoice number Kyro gave you. Kyro answers that it added 5 bags at 500 shillings to the invoice. Without a number it uses the latest invoice. An invoice holds one currency only, so Kyro will not mix shillings and dollars on one.`, ["The invoice number", "What you sold and the price of each"], null, "Kyro has said it added your item to the invoice.", []),
      S("See your invoices and who owes you", `Say "Show my invoices." Kyro lists each invoice with the customer, the amount, and whether it is paid, and the total not yet paid. Say "Who owes me money?" for only the unpaid ones, and "Show my overdue invoices" for the ones past their due date.`, ["Your phone or computer with Kyro open"], null, "Kyro has listed your invoices and what is not paid.", []),
      S("Mark an invoice paid", `When the customer pays you, say "Mark invoice INV-1001 as paid." Use your own invoice number. Kyro asks if it should go ahead. Say yes. Kyro answers that it marked the invoice paid. Say "Show my invoices" again, and it should now show paid. Kyro does not take money for you.`, ["The invoice number, and the money in your hand"], null, "Kyro says the invoice is marked paid and it shows as paid in the list.", []),
      S("Get a printable PDF", `The PDF is made on the Business services page, not by voice. Open the page, find Invoices and Receipts, and press Generate invoice PDF. The PDF appears in the file list with the items and the total, and you can download and print it. Kyro cannot send or print an invoice by voice. Give it to your customer yourself.`, ["The Business services page open"], null, "you have downloaded the PDF of your invoice.", [W("PDF", "a file that looks the same on every phone or computer and can be printed.")]),
      S("Fix a mistake", `The sheets say there is no voice command to delete or edit an invoice or an item. Use the Business services page for that. If the invoice number is not the one you expected, use the number Kyro told you. If you are not sure how to fix something on the page, ask the owner or your helper.`, ["The Business services page open"], null, "you know a mistake on an invoice is fixed on the page and not by voice.", [])
    ]
  },

  "property": {
    title: "Using property listings and showings",
    topic: "howto-property", phrase: "using property listings and showings",
    steps: [
      S("Learn what the property tools do", `The property tools are for an agent, a landlord or a property manager. A listing holds an address, a price, a type, the bedrooms and bathrooms, and a status. People such as buyers, sellers and tenants go in the same customer list, and a showing is saved as an appointment. You need a business workspace first. Nothing is published or sent. Commissions, market comparisons and contracts are not built.`, ["Your phone or computer with Kyro open and a business workspace started"], null, "you can say that a showing is saved as an appointment and not as a listing.", [KYRO, W("Listing", "a property you have for sale or rent, with its address and price."), W("Showing", "a time when someone comes to look at a property.")]),
      S("Add a listing", `Say "Add a listing at 123 Main Street for $450,000." The address must start with a number. Kyro asks if it should go ahead, so say yes. Kyro answers that it listed the address at that price as active. The dollar amount may print without a comma. That is a known quirk.`, ["The full address, starting with a number", "The price"], null, "Kyro has said it listed your property as active.", []),
      S("Hear your listings", `Say "What listings do I have?" Kyro reads each listing with its status and price. The same address can be listed twice, and Kyro does not stop you, so check that you did not add one twice.`, ["Your phone or computer with Kyro open"], null, "Kyro has read your listings back.", []),
      S("Mark a listing sold", `Say "Mark the listing at 123 Main Street as sold." Say the full address as you saved it, and use the word listing. Kyro asks if it should go ahead. Say yes. The status becomes sold. Other statuses are pending, under contract and off market.`, ["The address as you saved it"], null, "Kyro has said the listing is now sold.", []),
      S("Add a showing", `Say "Add a showing at 12 Moi Avenue tomorrow at 3pm." Use your own address, day and time. Kyro adds an appointment called Showing at that address. It is a local plan and is not copied to a real calendar. Use the word showing or viewing. The phrase open house makes a second listing by mistake.`, ["The address, the day and the time"], null, "Kyro has said it added a showing as an appointment.", []),
      S("Add a buyer or seller", `Say add a buyer named, then the name, for example James Mwangi. Add one person in each sentence. You can also say seller, tenant or landlord. Then say "Who are my buyers?" to hear them back. To change a price or a status, open the Property Listings section on the Business services page, change the row, and press Save changes.`, ["The name of a buyer"], null, "Kyro has named the buyer you added.", []),
      S("Know what the property tools cannot do", `There is no search by status, price or bedrooms. There are no lease or sale documents, so a request for a service agreement gives the general one. Kyro does not publish listings, contact buyers, or sign anything. Ask a real estate professional about contracts.`, ["Your phone or computer with Kyro open"], null, "you can name two things the property tools do not do.", [])
    ]
  },

  "drafts": {
    title: "Making drafts: flyers, agreements, plans and pitches",
    topic: "howto-drafts", phrase: "making flyer, agreement and pitch drafts",
    steps: [
      S("Learn what a draft is", `A draft from Kyro is an editable starting point made from a template. It is not written by artificial intelligence, and it is not live research. Nothing is sent, published, signed or booked. You read it, change it, and decide what to do. You need a business workspace first. Kyro builds outlines from the goal in your workspace, so set a clear goal first.`, ["Your phone or computer with Kyro open and a business workspace started"], null, "you can say that a draft is a starting point and nothing is sent.", [KYRO, W("Draft", "a first version that you read and change before you use it."), W("Template", "a ready-made shape with blanks for your own words.")]),
      S("Use the right words", `Say create, make or draft. The sheets say write a flyer and write a newsletter are not understood. Try the examples in the next steps exactly as they are written. If Kyro does not understand, change the first word to create or draft.`, ["Your phone or computer with Kyro open"], null, "you know to start with create, make or draft.", []),
      S("Make a service agreement draft", `Say "Create a service agreement." After you say yes, Kyro makes three files: a service agreement, a client intake form and an application checklist. The agreement says it is a template and not legal advice. Have someone who knows the law read it before anyone signs. Kyro does not sign anything.`, ["Your phone or computer with Kyro open"], null, "you have the three draft files, and you know to have the agreement read before anyone signs.", [W("Service agreement", "a paper that says what work will be done, for how long and for what payment.")]),
      S("Make marketing drafts", `Say "Create a newsletter." Kyro makes a newsletter and a promotional email as drafts, and also a flyer. You can say "Create marketing material" for the same set. The words are written for customers even in a nonprofit. Kyro does not send the email or print the flyer.`, ["Your phone or computer with Kyro open"], null, "you have newsletter, email and flyer drafts, and you know Kyro sends nothing.", []),
      S("Make a pitch outline", `Say "Draft an investor pitch." Or say "Make a pitch deck." Kyro makes an outline with the headings and prompts to fill in. It is draft structure only, with no live research. You write the real facts. Read each prompt and answer it with your own numbers.`, ["Your numbers and your story, written on paper"], null, "you have a pitch outline with headings and prompts.", []),
      S("Fill in a business plan", `On the Business services page, fill the seven boxes of the Business Plan section and press Save changes. Then say "Generate the business plan PDF." Boxes you did not fill print as not yet written. Kyro does not write the plan for you. Say "Show my business plan" to see what is saved.`, ["The Business services page open", "Your own words for the seven boxes"], null, "you have a business plan PDF with your own words in it.", []),
      S("Find, edit and download your drafts", `The Generate drafts section of the Business services page has a file list and a button to download all drafts as a zip file. Open the drafts, change the words, and check every fact. Nothing leaves Kyro until you send or print it yourself.`, ["The Business services page open"], null, "you have found your drafts in the file list.", [W("Zip file", "one file that holds many files together, so you can download them in one go.")])
    ]
  },

  "jobs": {
    title: "Using job search and lessons",
    topic: "howto-jobs", phrase: "using the job search and lessons",
    steps: [
      S("Learn what job search and lessons are", `Job search looks on the web for jobs near a place. It is a web search, not a list from employers. Kyro does not apply for you, nothing is posted, and no employer is contacted. You apply on the website yourself. Lessons are short explanations. They are Kyro's own text, with no real school and no certificate you can show an employer.`, ["Your phone or computer with Kyro open and online"], null, "you can say that Kyro only finds jobs and you apply yourself.", [KYRO, W("Web search", "looking for pages on the internet that match your words.")]),
      S("Search for a job", `Say "Find me a job in Kisumu." Use your own town. Kyro answers that it found some listings, with the job titles, and a button for each one. You can also say "Find jobs near me." Do not say I am looking for farm work in Nakuru, because Kyro takes that as a fact about where you live and not a search.`, ["The name of your town", "The kind of work you want"], null, "a list of jobs is on your screen.", []),
      S("Open a job and apply yourself", `Tap one of the job buttons. The website opens in a new tab. Read the job on that site. If you want it, apply on that site yourself. Kyro does not check that these jobs are real or that the employer is honest, so be careful with your personal details.`, ["Your phone or computer with Kyro open"], null, "you have opened one job's website and read it.", []),
      S("Get your résumé ready", `Employers often ask for a résumé. Say "Build my resume." Kyro asks one question at a time, reads back what it has, and after your yes makes a résumé you can download as a PDF. Whether the PDF downloads on a real phone has not been checked, so look at it before you rely on it.`, ["Your name, town, work you have done, skills, school and languages"], null, "you have started or finished your résumé.", [W("Résumé", "a short paper that lists your work, skills and school, so an employer can see what you can do.")]),
      S("Open the lessons", `Say "Open learning." The learning screen opens with buttons such as Teach me letters and Start the AI basics course. Or say "Teach me about irrigation basics." Kyro gives a short plain explanation. By voice it may say it found a matching lesson. Typed, you may get a general answer instead. Both are fine.`, ["A topic you want to learn"], null, "a lesson or a short explanation is on your screen.", []),
      S("Know what to trust", `Job results are only a web search. Applications and a hiring pipeline are notebooks only. Nothing is sent and no employer is contacted. Lessons are Kyro's own text, with no real school, so do not tell an employer you have a certificate from Kyro. Keep the pages you apply on written down, so you know where you applied.`, ["A pen and paper to write down where you applied"], null, "you know Kyro does not apply for you and that its lessons carry no certificate.", [])
    ]
  }
};
